// intake.conditionalStart.authorise — E2 AC4, SOP-DEL-01 §9. Generated by `pnpm gen:command`; guard cases kept,
// acceptance cases added.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createFakeClock, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Conflict,
  Forbidden,
  grantOf,
  NotFound,
  openTestKernel,
  RuleViolation,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { authoriseConditionalStart } from '../commands/authorise-conditional-start.ts';
import { saveHandoverCard } from '../commands/save-handover-card.ts';

const sponsor = aStaffActor({ roles: ['sponsor'] });
const director = aStaffActor({ roles: ['director'] });
const sales = aStaffActor({ roles: ['sales'] });
const clock = createFakeClock(new Date('2026-11-20T09:00:00Z')); // Friday; +5 working days (GB) = 27 Nov
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
const rows = (from: string) => countRows(testDb.url, from, []);
const authorise = (input: Record<string, unknown>, actor = sponsor) =>
  t.kernel.execute(
    authoriseConditionalStart,
    actor,
    {
      siteId: siteA,
      missingItems: ['A1', 'C2'],
      deadline: '2026-11-27',
      writtenRef: 'DingTalk msg 0001',
      ...input,
    },
    'test',
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url, { clock: clock.now });
  t.grant(director, createClient.permission, createSite.permission);
  t.grant(sponsor, authoriseConditionalStart.permission);
  t.grant(sales, saveHandoverCard.permission);
  const a = await t.kernel.execute(
    createClient,
    director,
    { shortCode: 'CLIENTA', name: 'Client A' },
    'test',
  );
  const place = { countryCode: 'GB', cityCode: 'LON', cityName: 'London', name: 'Mall A', standard: 'L' };
  ({ id: siteA } = await t.kernel.execute(createSite, director, { clientId: a.id, ...place }, 'test'));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('intake.conditionalStart.authorise', () => {
  it('is for the sponsor only — not even the Delivery Director', async () => {
    expect(grantOf(authoriseConditionalStart.permission)?.roles).toEqual(['sponsor']);
    await expect(authorise({}, director)).rejects.toBeInstanceOf(Forbidden);
  });

  it('needs a card before acceptance, the missing items and the written reference', async () => {
    await expect(authorise({})).rejects.toBeInstanceOf(NotFound);
    const content = { identification: { projectName: 'Mall A counting', projectType: 'new' } };
    const draft = { siteId: siteA, content, items: [], installsOrConfigures: true, newClientOrPlace: true };
    await t.kernel.execute(saveHandoverCard, sales, draft, 'test');
    for (const bad of [{ missingItems: [] }, { missingItems: ['A1', 'A1'] }, { writtenRef: ' ' }]) {
      await expect(authorise(bad)).rejects.toBeInstanceOf(ValidationFailed);
    }
  });

  it('refuses a deadline beyond 5 working days, recording nothing', async () => {
    await expect(authorise({ deadline: '2026-11-30' })).rejects.toBeInstanceOf(RuleViolation);
    expect(await rows('conditional_start')).toBe(0);
  });

  it('records the authorisation once per card version, with event and audit', async () => {
    const r = await authorise({});
    expect([r.version, r.latestDeadline]).toEqual([1, '2026-11-27']);
    expect(
      await rows(`conditional_start WHERE missing_items = '{A1,C2}' AND written_ref = 'DingTalk msg 0001'`),
    ).toBe(1);
    expect(await rows(`outbox WHERE event_type = 'intake.conditionalStart.authorised'`)).toBe(1);
    await expect(authorise({})).rejects.toBeInstanceOf(Conflict);
  });
});
